//! L2 verification gate (spec §6): sage-core behavior vs **goldens extracted
//! from the original binary** (`game/game.dat`, sha256-pinned in
//! `l2/l2_goldens.rs`, regenerated by `tools/l2/extract_goldens.py`).
//!
//! The oracle here is independent of our decompilation reading: table contents
//! and MD5 constants/imm32-presence come from the game image bytes; MD5 digest
//! vectors come from RFC 1321. Rows gated by this file are ledger-`verified`.

#[path = "l2/l2_goldens.rs"]
mod goldens;

use sage_core::flagname::{flag_name, name_at, scan_name, scan_pair, set_flag_by_name};
use sage_core::md5;

/// Every golden name must scan to its golden index in every table the
/// `scan_name` family mirrors (rows `0x004b42ca` `0x0068c7ad` `0x0068c7e3`
/// `0x0068c819` `0x0068c84f` `0x006aa2f9` `0x008bdc6d` `0x008dc696` `0x008dc6cc`),
/// case-insensitively, and a near-miss must miss.
#[test]
fn l2_scan_name_roundtrip_all_tables() {
    let tables: &[(&str, &[&str])] = &[
        ("model-condition", goldens::MODEL_CONDITION),
        ("disabled", goldens::DISABLED),
        ("kindof", goldens::KINDOF),
        ("weaponset", goldens::WEAPONSET),
        ("destroyed", goldens::DESTROYED),
        ("special", goldens::SPECIAL),
        ("emotion", goldens::EMOTION),
        ("emotion_ai", goldens::EMOTION_AI),
        ("vet21", goldens::VET21),
        ("autoresolve", goldens::AUTORESOLVE),
    ];
    for (label, table) in tables {
        for (i, name) in table.iter().enumerate() {
            assert_eq!(scan_name(table, name), i as i32, "{label}: {name}");
            // case-insensitive hit at the same index
            let upper: String = name.to_ascii_uppercase();
            assert_eq!(scan_name(table, &upper), i as i32, "{label}: {upper}");
        }
        // near-miss: prefix of the first entry + '!' must not match anything
        assert_eq!(scan_name(table, &format!("{}!", table[0])), -1);
    }
}

/// Bitset → name rows (`0x004454f3` `0x0068c6fb` `0x0068c725` `0x0068c753`
/// `0x0068c783` `0x006aa2cf` `0x008be0c7`): a set bit must yield the golden
/// string at that index; a clear bit yields None. Spot-check first/middle/last
/// of every table (full sweep would replicate the scan test).
#[test]
fn l2_flag_name_against_golden_tables() {
    let tables: &[&[&str]] = &[
        goldens::MODEL_CONDITION,
        goldens::DISABLED,
        goldens::KINDOF,
        goldens::WEAPONSET,
        goldens::DESTROYED,
        goldens::SPECIAL,
        goldens::EMOTION,
        goldens::EMOTION_AI,
        goldens::VET21,
        goldens::AUTORESOLVE,
    ];
    for table in tables {
        let words = table.len() / 32 + 1;
        for &i in &[0usize, table.len() / 2, table.len() - 1] {
            let mut block = vec![0u32; words];
            block[i >> 5] |= 1 << (i & 0x1f);
            assert_eq!(flag_name(&block, table, i as u32), Some(table[i]));
            block[i >> 5] = 0;
            assert_eq!(flag_name(&block, table, i as u32), None);
        }
    }
}

/// Set-by-name rows (`0x0068f6bc` `0x0068f733` `0x0068f762` `0x0068f7d9`
/// `0x006aad23` `0x008be0f1`): golden names must hit (return 1, bit set at the
/// golden index); non-members must return the exact masked sentinel —
/// byte-test callers see `0`, int-test callers see `0xFFFFFF00` — with the
/// block untouched.
#[test]
fn l2_set_flag_by_name_gate() {
    for table in [goldens::KINDOF, goldens::SPECIAL, goldens::DESTROYED] {
        let words = table.len() / 32 + 1;
        for &i in &[0usize, table.len() - 1] {
            let mut block = vec![0u32; words];
            assert_eq!(set_flag_by_name(&mut block, table, table[i]), 1);
            assert_eq!(block[i >> 5], 1 << (i & 0x1f));
        }
        let mut block = vec![0u32; words];
        let miss = set_flag_by_name(&mut block, table, "NOT_A_GAME_NAME_AT_ALL");
        assert_eq!(miss as u8, 0, "byte-test callers must see 0");
        assert_eq!(miss as u32, 0xffff_ff00, "int callers see the masked sentinel");
        assert_eq!(block, vec![0u32; words]);
    }
}

/// `name_at` rows: KindOf `0x00706218` (max `0xd9` = table.len()-1 from the
/// binary) and auto-resolve `0x00818be3` (max 7). Bounds and contents come
/// from the golden tables.
#[test]
fn l2_name_at_bounds_from_binary() {
    assert_eq!(goldens::KINDOF.len(), 218); // max index 0xd9
    assert_eq!(name_at(goldens::KINDOF, 0xd9), Some(goldens::KINDOF[217]));
    assert_eq!(name_at(goldens::KINDOF, 218), None);
    assert_eq!(name_at(goldens::KINDOF, -1), None);
    assert_eq!(goldens::AUTORESOLVE.len(), 8);
    assert_eq!(name_at(goldens::AUTORESOLVE, 7), Some(goldens::AUTORESOLVE[7]));
    assert_eq!(name_at(goldens::AUTORESOLVE, 8), None);
}

/// Pair-map row `0x005db3fe`: the table at `0x00bda640` is the 125-entry
/// command-name → id map (`SAVE_VIEW1`=36 … `DEBUG_TOGGLE_STRINGTAGS`=160);
/// lookups must return the golden ids, case-insensitively, NULL-terminated.
#[test]
fn l2_command_name_map_gate() {
    assert_eq!(goldens::COMMAND_NAME_IDS.len(), 125);
    assert_eq!(goldens::COMMAND_NAME_IDS[0], ("SAVE_VIEW1", 36));
    assert_eq!(
        goldens::COMMAND_NAME_IDS[124],
        ("DEBUG_TOGGLE_STRINGTAGS", 160)
    );
    // scan_pair models the game's pointer cell: it borrows the value cells.
    let table: Vec<(&str, &u32)> = goldens::COMMAND_NAME_IDS.iter().map(|(n, v)| (*n, v)).collect();
    assert_eq!(scan_pair(&table, "save_view3"), Some(&38));
    assert_eq!(scan_pair(&table, "Debug_Toggle_StringTags"), Some(&160));
    assert_eq!(scan_pair(&table, "SOME_VIEW9"), None);
}

/// MD5 rows (`0x00a06220` `0x00a06320` `0x00a06360` `0x00a06c40` `0x00a06d00`
/// `0x00a06db0`): golden padding blob from `DAT_00dd5158` must equal the
/// mirror's constant; RFC 1321 vectors gate the end-to-end digest. K-table
/// presence in the game transform bytes (`0x00a06360`) was asserted at golden
/// generation time.
#[test]
fn l2_md5_gate() {
    assert_eq!(md5::MD5_PADDING, goldens::MD5_PADDING_GOLDEN);
    assert_eq!(goldens::MD5_K[0], 0xd76a_a478);
    assert_eq!(goldens::MD5_K[63], 0xeb86_d391);
    let hex = |s: &[u8]| {
        let out = md5::md5_hex(s);
        core::str::from_utf8(&out[..32]).unwrap().to_string()
    };
    // RFC 1321 A.5 test suite
    assert_eq!(hex(b""), "d41d8cd98f00b204e9800998ecf8427e");
    assert_eq!(hex(b"a"), "0cc175b9c0f1b6a831c399e269772661");
    assert_eq!(hex(b"abc"), "900150983cd24fb0d6963f7d28e17f72");
    assert_eq!(hex(b"message digest"), "f96b697d7cb7938d525a2f31aaf161d0");
    assert_eq!(
        hex(b"abcdefghijklmnopqrstuvwxyz"),
        "c3fcd3d76192e4007dfb496cca67e13b"
    );
    assert_eq!(
        hex(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"),
        "d174ab98d277d9f5a5611c2c9f419d9f"
    );
    assert_eq!(
        hex(b"12345678901234567890123456789012345678901234567890123456789012345678901234567890"),
        "57edf4a22be3c955ac49da2e2107b67a"
    );
}
